#include <iostream>
#include <vector>
using namespace std;

const int TABLE_SIZE = 10;

// Hash Function
int hashFunction(int key) {
    return key % TABLE_SIZE;
}

// -------------------- Linear Probing --------------------
class LinearProbing {
    pair<int, int> table[TABLE_SIZE];
    bool occupied[TABLE_SIZE] = {false};

public:
    void insert(int key, int value) {
        int index = hashFunction(key);
        while (occupied[index]) {
            index = (index + 1) % TABLE_SIZE;
        }
        table[index] = {key, value};
        occupied[index] = true;
    }

    int search(int key) {
        int index = hashFunction(key), comparisons = 1;
        while (occupied[index] && table[index].first != key) {
            index = (index + 1) % TABLE_SIZE;
            comparisons++;
        }
        if (occupied[index] && table[index].first == key)
            cout << "Found key " << key << " in " << comparisons << " comparisons.\n";
        else
            cout << "Key " << key << " not found after " << comparisons << " comparisons.\n";
        return comparisons;
    }
};

// -------------------- Chaining --------------------
class Chaining {
    vector<pair<int, int>> table[TABLE_SIZE];

public:
    void insert(int key, int value) {
        table[hashFunction(key)].emplace_back(key, value);
    }

    int search(int key) {
        int index = hashFunction(key), comparisons = 0;
        for (auto& pair : table[index]) {
            comparisons++;
            if (pair.first == key) {
                cout << "Found key " << key << " in chain with " << comparisons << " comparisons.\n";
                return comparisons;
            }
        }
        cout << "Key " << key << " not found in chain after " << comparisons << " comparisons.\n";
        return comparisons;
    }
};

// -------------------- Main --------------------
int main() {
    LinearProbing lp;
    Chaining ch;

    // Linear Probing
    lp.insert(10, 100);
    lp.insert(20, 200);
    lp.insert(30, 300);
    lp.insert(21, 210);
    lp.search(21);
    lp.search(50);

    // Chaining
    ch.insert(10, 100);
    ch.insert(20, 200);
    ch.insert(30, 300);
    ch.insert(20, 250);
    ch.search(20);
    ch.search(40);

    return 0;
}
