#include <vector>
using namespace std;

class SetADT {
private:
    vector<int> elements;

public:
    // Add element if not already present
    void add(int element) {
        if (!contains(element))
            elements.push_back(element);
    }

    // Remove element if present
    void remove(int element) {
        for (auto it = elements.begin(); it != elements.end(); ++it) {
            if (*it == element) {
                elements.erase(it);
                break;
            }
        }
    }

    // Check if element is in set
    bool contains(int element) const {
        for (int e : elements) {
            if (e == element)
                return true;
        }
        return false;
    }

    // Return size of the set
    int size() const {
        return elements.size();
    }

    // Return elements as vector (for iteration)
    vector<int> getElements() const {
        return elements;
    }

    // Intersection of two sets
    SetADT intersection(const SetADT& other) const {
        SetADT result;
        for (int e : elements) {
            if (other.contains(e))
                result.add(e);
        }
        return result;
    }

    // Union of two sets
    SetADT unionSet(const SetADT& other) const {
        SetADT result;
        for (int e : elements)
            result.add(e);
        for (int e : other.getElements())
            result.add(e);
        return result;
    }

    // Difference of two sets (this - other)
    SetADT difference(const SetADT& other) const {
        SetADT result;
        for (int e : elements) {
            if (!other.contains(e))
                result.add(e);
        }
        return result;
    }

    // Check if current set is subset of other set
    bool isSubset(const SetADT& other) const {
        for (int e : elements) {
            if (!other.contains(e))
                return false;
        }
        return true;
    }

